import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Route, Router } from '@angular/router';
import { AuthService } from 'src/app/service/auth.service';
import { Company } from '../../Models/Company';

@Component({
  selector: 'app-company',
  templateUrl: './company.component.html',
  styleUrls: ['./company.component.css']
})
export class CompanyComponent {
constructor(private route : Router , private service : AuthService , private fb : FormBuilder){}

login(){
  this.route.navigate(['/login']);
}
 signUp(){
  this.route.navigate(['/register']);
}

companyReg = this.fb.group({
    companyName :['',Validators.required],
    email :['',Validators.required],
    password :['',Validators.required],
    website :['',Validators.required],
    location :['',Validators.required],
    description :['',Validators.required]
})

register() {
  this.service.signUpCompany(this.companyReg.value as Company).subscribe({
    next: (res) => {
      console.log("SUCCESS", res);
    },
    error: (err) => {
      console.log("ERROR", err);
      console.log("Status:", err.status);
      console.log("Body:", err.error);
    }
  });
}

submit(){
  console.log(this.companyReg.value)
  this.register();
   this.companyReg.reset;
   if(this.companyReg.valid){
    alert("Company Created !\n Welcome to Hirehub.")
    this.route.navigate(['/login']);
   }
   else{
    alert(`Something Went Wrong.\n Please try again`);
   }
}

}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Register — Company · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">
</head>
<body>
<div class="page">
<header class="topnav">
  <div class="wrap">
    <a href="index.html" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links">
      <a href="jobs.html">Find Jobs</a>
      <a href="companies.html">Companies</a>
      <a href="register-company.html">For Employers</a>
    </nav>
    <div class="nav-actions">
      <a (click)="login()" class="btn btn-ghost-dark btn-sm">Log in</a>
      <a (click)="signUp()" class="btn btn-primary btn-sm">Sign up</a>
    </div>
  </div>
</header>

<div class="auth-wrap">
  <div class="auth-card">
  <form [formGroup]="companyReg" (ngSubmit)="submit()">
    <h2>Create your Company account</h2>
    <div class="field"><label>Company name</label><input formControlName="companyName" placeholder="Nimbus Cloud"></div>
    <div class="field"><label>Email</label><input formControlName="email" type="email" placeholder="hr@nimbuscloud.io"></div>
    <div class="field"><label>Password</label><input formControlName="password" type="password" placeholder="••••••••"></div>
    <div class="field"><label>Website</label><input formControlName="website" placeholder="nimbuscloud.io"></div>
    <div class="field"><label>Location</label><input formControlName="location" placeholder="Kochi, IN"></div>
    <div class="field"><label>Description</label><textarea formControlName="description" placeholder="What does the company do?"></textarea></div>
    <button type="submit" class="btn btn-primary btn-block">Create company account</button>
  </form>
  </div>
</div>

<footer class="site-footer">
  <div class="wrap">
    <span>© 2026 HireHub</span>
    <span class="mono-label" style="color:var(--muted-lt)">com.aitrich.JobPortalSystem</span>
  </div>
</footer>
</div>
</body>
</html>
